properties.query:
// Detects suspicious child processes of Microsoft OneNote
let ProcessNames = dynamic(["explorer.exe"]);
let parent_processes = dynamic(["onenote.exe"]);
let cmd_all = dynamic(["ifm","create full"]);
let cmd_any = dynamic([".hta",".vb",".wsh",".js",".ps",".scr",".pif",".bat",".cmd"]);
_Im_ProcessCreate(targetprocess_has_any=ProcessNames,parentprocess_has_any=parent_processes,commandline_has_any=cmd_any)
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
